create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
alter default privileges in schema private revoke execute on functions from public;
grant usage on schema private to authenticated;
create table if not exists private.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null check(length(name) between 2 and 80),track text not null default 'Admission',daily_goal integer not null default 20 check(daily_goal between 5 and 100),leaderboard boolean not null default false,created_at timestamptz not null default now());
create table if not exists private.exam_catalog(id text primary key,meta jsonb not null,questions jsonb not null);
create table if not exists private.attempts(id text primary key default 'at_'||gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,exam_id text not null,title text not null,subject text not null,module_id text,source text not null default 'starter',questions jsonb not null,answers jsonb not null default '{}',marked jsonb not null default '[]',started_at bigint not null,deadline bigint not null,submitted_at bigint,score numeric not null default 0,total integer not null,correct integer not null default 0,wrong integer not null default 0,skipped integer not null default 0,elapsed integer not null default 0,penalty numeric not null default 0,status text not null default 'active' check(status in ('active','submitted')));
create unique index if not exists one_active_attempt on private.attempts(user_id) where status='active';
create index if not exists attempts_history on private.attempts(user_id,submitted_at desc);
create index if not exists attempts_class on private.attempts(exam_id,status);
create table if not exists private.bookmarks(user_id uuid not null references auth.users(id) on delete cascade,question_id text not null,question jsonb not null,created_at timestamptz not null default now(),primary key(user_id,question_id));
create table if not exists private.planner(id text primary key default 'task_'||gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 2 and 100),date date not null,minutes integer not null check(minutes between 5 and 180),done boolean not null default false);
create index if not exists planner_owner_date on private.planner(user_id,date);
create table if not exists private.classrooms(id text primary key default 'cl_'||gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 3 and 100),code text not null unique default upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),created_at timestamptz not null default now());
create index if not exists class_owner on private.classrooms(owner_id);
create table if not exists private.class_members(class_id text not null references private.classrooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(class_id,user_id));
create index if not exists members_owner on private.class_members(user_id);
create table if not exists private.teacher_questions(id text primary key default 'tq_'||gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,class_id text not null references private.classrooms(id) on delete cascade,content jsonb not null,created_at timestamptz not null default now());
create index if not exists teacher_question_class on private.teacher_questions(class_id,owner_id);
create table if not exists private.class_exams(id text primary key default 'class_'||gen_random_uuid(),class_id text not null references private.classrooms(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,title text not null,questions jsonb not null,minutes integer not null check(minutes between 1 and 120),created_at timestamptz not null default now());
create index if not exists exam_class on private.class_exams(class_id);
create table if not exists private.payments(id text primary key,user_id uuid not null references auth.users(id) on delete cascade,plan text not null check(plan in ('monthly','yearly')),amount_minor integer not null check(amount_minor in (19900,179900)),status text not null default 'pending' check(status in ('pending','paid','failed','review')),created_at bigint not null,confirmed_at bigint,validation_id text unique);
create index if not exists payment_owner on private.payments(user_id,confirmed_at);
create table if not exists private.generations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,module_id text not null,day date not null default (now() at time zone 'Asia/Dhaka')::date,status text not null default 'pending',created_at timestamptz not null default now());
create index if not exists generation_quota on private.generations(day,user_id,status);
create table if not exists private.activity(attempt_id text primary key references private.attempts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,day date not null,answered integer not null,correct integer not null,seconds integer not null);
create index if not exists activity_owner_day on private.activity(user_id,day);
create table if not exists private.question_reports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,question_id text not null,reason text not null check(length(reason) between 5 and 1000),created_at timestamptz not null default now());
create table if not exists private.request_limits(user_id uuid not null references auth.users(id) on delete cascade,bucket bigint not null,count integer not null,primary key(user_id,bucket));
do $$declare t record;begin for t in select tablename from pg_tables where schemaname='private' loop execute format('alter table private.%I enable row level security',t.tablename);if not exists(select 1 from pg_policies where schemaname='private' and tablename=t.tablename and policyname='deny_direct_access') then execute format('create policy deny_direct_access on private.%I to anon,authenticated using(false) with check(false)',t.tablename);end if;end loop;end$$;
revoke all on all tables in schema private from anon,authenticated;
create or replace function private.guard() returns uuid language plpgsql stable security definer set search_path='' as $$declare uid uuid:=auth.uid();begin if uid is null then raise exception 'AUTH_REQUIRED';end if;if exists(select 1 from auth.mfa_factors f where f.user_id=uid and f.status='verified') and coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception 'MFA_REQUIRED';end if;return uid;end$$;
create or replace function private.plan(uid uuid) returns jsonb language plpgsql stable set search_path='' as $$declare expiry bigint:=0;r record;ms bigint:=floor(extract(epoch from now())*1000);begin for r in select * from private.payments p where p.user_id=uid and status='paid' order by confirmed_at,id loop expiry:=greatest(expiry,r.confirmed_at)+(case when r.plan='monthly' then 30 else 365 end)::bigint*86400000;end loop;return jsonb_build_object('plus',expiry>ms,'expiresAt',nullif(expiry,0));end$$;
create or replace function private.finish(aid text,uid uuid) returns private.attempts language plpgsql set search_path='' as $$declare a private.attempts;q jsonb;v jsonb;ms bigint:=floor(extract(epoch from now())*1000);c int:=0;w int:=0;s int:=0;begin select * into a from private.attempts where id=aid and user_id=uid for update;if not found then raise exception 'NOT_FOUND';end if;if a.status='submitted' then return a;end if;for q in select value from jsonb_array_elements(a.questions) loop v:=a.answers->(q->>'id');if v is null then s:=s+1;elsif (v::text)::int=(q->>'answer')::int then c:=c+1;else w:=w+1;end if;end loop;update private.attempts set status='submitted',submitted_at=ms,score=c-w*a.penalty,correct=c,wrong=w,skipped=s,elapsed=greatest(0,least((ms-a.started_at)/1000,(a.deadline-a.started_at)/1000)) where id=aid returning * into a;insert into private.activity values(a.id,uid,(to_timestamp(ms/1000.0) at time zone 'Asia/Dhaka')::date,c+w,c,a.elapsed) on conflict(attempt_id) do nothing;return a;end$$;
create or replace function private.report(aid text,uid uuid) returns jsonb language plpgsql stable set search_path='' as $$declare a private.attempts;review jsonb;begin select * into a from private.attempts where id=aid and user_id=uid;if not found then raise exception 'NOT_FOUND';end if;if a.status<>'submitted' then raise exception 'REVIEW_LOCKED';end if;select jsonb_agg(q||jsonb_build_object('chosen',coalesce(a.answers->(q->>'id'),'null'::jsonb),'state',case when a.answers->(q->>'id') is null then 'skipped' when (a.answers->>(q->>'id'))::int=(q->>'answer')::int then 'correct' else 'wrong' end)) into review from jsonb_array_elements(a.questions) q;return (to_jsonb(a)-'questions')||jsonb_build_object('review',review,'accuracy',case when a.correct+a.wrong>0 then round(a.correct*100.0/(a.correct+a.wrong)) else 0 end);end$$;
create or replace function private.public_questions(qs jsonb) returns jsonb language sql immutable set search_path='' as $$select coalesce(jsonb_agg(q-'answer'-'explanation'),'[]'::jsonb) from jsonb_array_elements(qs) q$$;
create or replace function private.handle(action text,data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=private.guard();ms bigint:=floor(extract(epoch from now())*1000);a private.attempts;ex private.exam_catalog;cl private.classrooms;ce private.class_exams;qs jsonb;q jsonb;rid text;payload jsonb;plus boolean:=(private.plan(uid)->>'plus')::boolean;lim int;gid uuid;prof private.profiles;minute_count int;begin
perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
if action not in ('bootstrap','attempt','report','bookmarks','studio','class-results') then insert into private.request_limits values(uid,ms/60000,1) on conflict(user_id,bucket) do update set count=request_limits.count+1 returning count into lim;if lim>160 then raise exception 'RATE_LIMIT';end if;delete from private.request_limits where user_id=uid and bucket<ms/60000-10;end if;
insert into private.profiles(id,name) values(uid,left(case when length(coalesce(split_part(auth.jwt()->>'email','@',1),''))<2 then 'Learner' else split_part(auth.jwt()->>'email','@',1) end,80)) on conflict(id) do nothing;
if action='bootstrap' then
 select * into prof from private.profiles where id=uid;
 return jsonb_build_object('profile',to_jsonb(prof)||jsonb_build_object('leaderboard',case when prof.leaderboard then 1 else 0 end),'history',(select coalesce(jsonb_agg(to_jsonb(h)),'[]') from(select id,exam_id,title,subject,module_id,source,score,total,correct,wrong,skipped,elapsed,submitted_at from private.attempts where user_id=uid and status='submitted' order by submitted_at desc limit 500)h),'tasks',(select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('done',case when p.done then 1 else 0 end) order by p.date,p.id),'[]') from private.planner p where user_id=uid),'bookmarks',(select coalesce(jsonb_agg(question_id),'[]') from private.bookmarks where user_id=uid),'activeAttempt',(select jsonb_build_object('id',id,'title',title,'deadline',deadline) from private.attempts where user_id=uid and status='active' limit 1),'plan',private.plan(uid),'billing',(select coalesce(jsonb_agg(to_jsonb(b)),'[]') from(select id,plan,amount_minor,status,created_at,confirmed_at from private.payments where user_id=uid order by created_at desc limit 30)b),'activity',(select coalesce(jsonb_agg(to_jsonb(d)),'[]') from(select day,sum(answered)::int answered,sum(correct)::int correct,sum(seconds)::int seconds from private.activity where user_id=uid and day>=(now() at time zone 'Asia/Dhaka')::date-89 group by day order by day)d),'generationUsage',(select count(*) from private.generations where user_id=uid and day=(now() at time zone 'Asia/Dhaka')::date),'generationLimit',case when plus then 20 else 5 end);
elsif action in ('start','generated-create') then
 select * into a from private.attempts where user_id=uid and status='active' for update;if found then if a.deadline>ms then return jsonb_build_object('id',a.id,'resumed',true);else perform private.finish(a.id,uid);end if;end if;
 if action='generated-create' then
  gid:=(data->>'reservation')::uuid;select id::text into rid from private.generations where id=gid and user_id=uid and module_id=data->>'moduleId' and status='pending' and created_at>now()-interval '5 minutes' for update;if not found then raise exception 'INVALID: Generation request expired. Please try again.';end if;
  qs:=data->'questions';if jsonb_typeof(qs)<>'array' or jsonb_array_length(qs) not between 3 and 20 then raise exception 'INVALID: Invalid question set.';end if;
  for q in select value from jsonb_array_elements(qs) loop if length(q->>'stem') not between 8 and 1600 or jsonb_array_length(q->'options')<>4 or (q->>'answer')::int not between 0 and 3 or length(q->>'explanation') not between 10 and 2400 then raise exception 'INVALID: Question validation failed.';end if;end loop;
  insert into private.attempts(user_id,exam_id,title,subject,module_id,source,questions,started_at,deadline,total,penalty) values(uid,'generated-'||(data->>'moduleId'),left(data->>'title',120),left(data->>'subject',80),data->>'moduleId','AI-generated',qs,ms,ms+least(60,greatest(3,(data->>'minutes')::int))*60000,jsonb_array_length(qs),coalesce((data->>'penalty')::numeric,0)) returning id into rid;update private.generations set status='complete' where id=gid;
 else
  select * into ex from private.exam_catalog where id=data->>'examId';if found then
   if ex.id='daily-challenge' and ((now() at time zone 'Asia/Dhaka')::time<time '20:00' or (now() at time zone 'Asia/Dhaka')::time>=time '21:00') then raise exception 'CLOSED';end if;
   qs:=ex.questions;if coalesce((data->>'practice')::boolean,false) then select jsonb_agg(value) into qs from(select value from jsonb_array_elements(qs) limit 8)x;end if;
   insert into private.attempts(user_id,exam_id,title,subject,module_id,questions,started_at,deadline,total,penalty) values(uid,case when coalesce((data->>'practice')::boolean,false) then 'practice-'||ex.id else ex.id end,case when coalesce((data->>'practice')::boolean,false) then 'Daily practice · '||(ex.meta->>'subject') else ex.meta->>'title' end,ex.meta->>'subject',ex.id,(select jsonb_agg(value order by random()) from jsonb_array_elements(qs)),ms,ms+(case when coalesce((data->>'practice')::boolean,false) then 10 else (ex.meta->>'minutes')::int end)*60000,jsonb_array_length(qs),case when coalesce((data->>'practice')::boolean,false) then 0 else (ex.meta->>'penalty')::numeric end) returning id into rid;
  else
   select e.* into ce from private.class_exams e join private.classrooms c on c.id=e.class_id where e.id=data->>'examId' and(c.owner_id=uid or exists(select 1 from private.class_members m where m.class_id=c.id and m.user_id=uid));if not found then raise exception 'NOT_FOUND';end if;
   insert into private.attempts(user_id,exam_id,title,subject,source,questions,started_at,deadline,total) values(uid,ce.id,ce.title,'Classroom','Teacher-written',ce.questions,ms,ms+ce.minutes*60000,jsonb_array_length(ce.questions)) returning id into rid;
  end if;
 end if;return jsonb_build_object('id',rid);
elsif action='attempt' then
 select * into a from private.attempts where id=data->>'id' and user_id=uid;if not found then raise exception 'NOT_FOUND';end if;if a.status='submitted' then return jsonb_build_object('submitted',true,'id',a.id);end if;return (to_jsonb(a)-'questions')||jsonb_build_object('questions',private.public_questions(a.questions),'serverTime',ms);
elsif action in ('answer','mark','submit','report') then
 select * into a from private.attempts where id=data->>'id' and user_id=uid for update;if not found then raise exception 'NOT_FOUND';end if;
 if action='report' then return private.report(a.id,uid);elsif action='submit' then perform private.finish(a.id,uid);return private.report(a.id,uid);end if;
 if a.status<>'active' then raise exception 'ALREADY: This test has been submitted.';end if;if ms>=a.deadline then perform private.finish(a.id,uid);return jsonb_build_object('submitted',true,'id',a.id);end if;
 if action='answer' then select value into q from jsonb_array_elements(a.questions) where value->>'id'=data->>'questionId';if not found then raise exception 'INVALID: This question is not in your test.';end if;
  if data->'answer'='null'::jsonb then update private.attempts set answers=answers-(data->>'questionId') where id=a.id;elsif jsonb_typeof(data->'answer')='number' and (data->>'answer')~'^[0-3]$' then update private.attempts set answers=jsonb_set(answers,array[data->>'questionId'],data->'answer') where id=a.id;else raise exception 'INVALID: Choose a valid answer.';end if;
 else if jsonb_typeof(data->'marked')<>'array' or jsonb_array_length(data->'marked')>a.total or exists(select 1 from jsonb_array_elements_text(data->'marked') mark where not exists(select 1 from jsonb_array_elements(a.questions) qq where qq->>'id'=mark)) then raise exception 'INVALID: Invalid markers.';end if;update private.attempts set marked=data->'marked' where id=a.id;end if;return jsonb_build_object('saved',true);
elsif action='bookmarks' then return jsonb_build_object('questions',(select coalesce(jsonb_agg(question order by created_at desc),'[]') from private.bookmarks where user_id=uid));
elsif action in ('bookmark','question-report') then
 select q2.value into q from private.attempts at,jsonb_array_elements(at.questions) q2 where at.user_id=uid and at.status='submitted' and q2.value->>'id'=data->>'questionId' limit 1;if not found then raise exception 'REVIEW_LOCKED';end if;
 if action='question-report' then if length(trim(data->>'reason')) not between 5 and 1000 then raise exception 'INVALID: Describe the issue in 5 to 1000 characters.';end if;insert into private.question_reports(user_id,question_id,reason) values(uid,data->>'questionId',trim(data->>'reason'));elsif coalesce((data->>'saved')::boolean,false) then insert into private.bookmarks(user_id,question_id,question) values(uid,data->>'questionId',q) on conflict do nothing;else delete from private.bookmarks where user_id=uid and question_id=data->>'questionId';end if;return jsonb_build_object('saved',true);
elsif action='task-add' then
 if(select count(*) from private.planner where user_id=uid)>=200 then raise exception 'LIMIT: Your planner has reached its 200 task limit.';end if;insert into private.planner(user_id,title,date,minutes) values(uid,trim(data->>'title'),(data->>'date')::date,(data->>'minutes')::int);return jsonb_build_object('saved',true);
elsif action in ('task-toggle','task-delete') then
 if not exists(select 1 from private.planner where id=data->>'id' and user_id=uid) then raise exception 'NOT_FOUND';end if;if action='task-toggle' then update private.planner set done=(data->>'done')::boolean where id=data->>'id' and user_id=uid;else delete from private.planner where id=data->>'id' and user_id=uid;end if;return jsonb_build_object('saved',true);
elsif action='settings' then
 if data->>'track' not in ('Admission','BCS & Jobs','SSC & HSC','Skills') then raise exception 'INVALID: Choose a valid track.';end if;update private.profiles set name=trim(data->>'name'),track=data->>'track',daily_goal=(data->>'goal')::int,leaderboard=(data->>'leaderboard')::boolean where id=uid;return jsonb_build_object('saved',true);
elsif action='class-create' then
 if(select count(*) from private.classrooms where owner_id=uid)>=(case when plus then 10 else 1 end) then raise exception 'LIMIT: Free accounts support one classroom and Plus supports ten.';end if;insert into private.classrooms(owner_id,title) values(uid,trim(data->>'title'));return jsonb_build_object('saved',true);
elsif action='class-join' then
 select * into cl from private.classrooms where code=upper(trim(data->>'code'));if not found then raise exception 'NOT_FOUND';end if;if cl.owner_id=uid then raise exception 'ALREADY: You own this classroom.';end if;insert into private.class_members(class_id,user_id) values(cl.id,uid) on conflict do nothing;return jsonb_build_object('saved',true);
elsif action='question-create' then
 if not exists(select 1 from private.classrooms where id=data->>'classId' and owner_id=uid) then raise exception 'NOT_FOUND';end if;if(select count(*) from private.teacher_questions where owner_id=uid)>=(case when plus then 500 else 50 end) then raise exception 'LIMIT: Your question bank is full.';end if;
 if length(trim(data->>'stem')) not between 5 and 1200 or length(trim(data->>'explanation')) not between 5 and 2000 or jsonb_array_length(data->'options')<>4 or exists(select 1 from jsonb_array_elements_text(data->'options') o where length(trim(o)) not between 1 and 400) or (data->>'answer')!~'^[0-3]$' then raise exception 'INVALID: Check the question, four options, correct answer and explanation.';end if;
 rid:='tq_'||gen_random_uuid();insert into private.teacher_questions(id,owner_id,class_id,content) values(rid,uid,data->>'classId',jsonb_build_object('id',rid,'stem',trim(data->>'stem'),'options',data->'options','answer',(data->>'answer')::int,'explanation',trim(data->>'explanation'),'subject',left(data->>'subject',60),'category','Classroom','difficulty','Standard'));return jsonb_build_object('saved',true);
elsif action='class-publish' then
 if not exists(select 1 from private.classrooms where id=data->>'classId' and owner_id=uid) then raise exception 'NOT_FOUND';end if;select jsonb_agg(content order by created_at) into qs from private.teacher_questions where class_id=data->>'classId' and owner_id=uid;if qs is null or jsonb_array_length(qs)>50 then raise exception 'EMPTY: A classroom test needs 1 to 50 questions.';end if;if length(trim(data->>'title')) not between 3 and 120 then raise exception 'INVALID: Use a title with 3 to 120 characters.';end if;insert into private.class_exams(class_id,owner_id,title,questions,minutes) values(data->>'classId',uid,trim(data->>'title'),qs,(data->>'minutes')::int);return jsonb_build_object('saved',true);
elsif action='studio' then
 return jsonb_build_object('classes',(select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('members',(select count(*) from private.class_members m where m.class_id=c.id),'question_count',(select count(*) from private.teacher_questions tq where tq.class_id=c.id)) order by c.created_at desc),'[]') from private.classrooms c where c.owner_id=uid),'questions',(select coalesce(jsonb_agg(content||jsonb_build_object('class_id',class_id) order by created_at desc),'[]') from private.teacher_questions where owner_id=uid),'exams',(select coalesce(jsonb_agg((to_jsonb(e)-'questions')||jsonb_build_object('submissions',(select count(*) from private.attempts at where at.exam_id=e.id and at.status='submitted'))),'[]') from private.class_exams e where e.owner_id=uid),'joined',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'code',c.code)),'[]') from private.classrooms c join private.class_members m on m.class_id=c.id where m.user_id=uid),'assigned',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'minutes',e.minutes,'count',jsonb_array_length(e.questions),'class_title',c.title)),'[]') from private.class_exams e join private.classrooms c on c.id=e.class_id where c.owner_id=uid or exists(select 1 from private.class_members m where m.class_id=c.id and m.user_id=uid)));
elsif action='class-results' then
 if not exists(select 1 from private.classrooms where id=data->>'id' and owner_id=uid) then raise exception 'NOT_FOUND';end if;return jsonb_build_object('results',(select coalesce(jsonb_agg(jsonb_build_object('id',at.id,'title',at.title,'name',p.name,'score',at.score,'total',at.total,'correct',at.correct,'wrong',at.wrong,'elapsed',at.elapsed,'submitted_at',at.submitted_at) order by at.submitted_at desc),'[]') from private.attempts at join private.class_exams e on e.id=at.exam_id join private.profiles p on p.id=at.user_id where e.class_id=data->>'id' and e.owner_id=uid and at.status='submitted'));
elsif action='generation-reserve' then
 perform pg_advisory_xact_lock(47078123);if length(data->>'moduleId') not between 3 and 80 then raise exception 'INVALID: Choose a module.';end if;
 if(select count(*) from private.generations where user_id=uid and day=(now() at time zone 'Asia/Dhaka')::date)>=(case when plus then 20 else 5 end) or(select count(*) from private.generations where day=(now() at time zone 'Asia/Dhaka')::date)>=200 then raise exception 'RATE_LIMIT';end if;
 insert into private.generations(user_id,module_id) values(uid,data->>'moduleId') returning id into gid;return jsonb_build_object('reservation',gid);
elsif action='generation-failed' then update private.generations set status='failed' where id=(data->>'reservation')::uuid and user_id=uid and status='pending';return jsonb_build_object('saved',true);
elsif action='checkout-order' then
 if data->>'plan' not in ('monthly','yearly') then raise exception 'INVALID: Choose a valid plan.';end if;if(select count(*) from private.payments where user_id=uid and created_at>ms-600000)>=4 then raise exception 'RATE_LIMIT';end if;rid:='pk_'||substr(replace(gen_random_uuid()::text,'-',''),1,24);insert into private.payments values(rid,uid,data->>'plan',case when data->>'plan'='monthly' then 19900 else 179900 end,'pending',ms,null,null);return (select to_jsonb(p) from private.payments p where id=rid);
else raise exception 'INVALID: Unknown action.';end if;
end$$;
create or replace function public.porikkhon(action text,data jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$select private.handle(action,data)$$;
revoke all on function public.porikkhon(text,jsonb) from public,anon;
grant execute on function public.porikkhon(text,jsonb) to authenticated;
grant execute on function private.handle(text,jsonb) to authenticated;
create or replace function private.ranking() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(r)),'[]')) from(select name,score,total,elapsed from(select distinct on (at.user_id) p.name,at.score,at.total,at.elapsed from private.attempts at join private.profiles p on p.id=at.user_id where p.leaderboard and at.status='submitted' and at.exam_id='daily-challenge' and at.submitted_at>=extract(epoch from now()-interval '7 days')*1000 order by at.user_id,at.score/at.total desc,at.elapsed asc) x order by score/total desc,elapsed limit 25)r$$;
create or replace function public.porikkhon_leaderboard() returns jsonb language sql security invoker set search_path='' as $$select private.ranking()$$;
grant usage on schema private to anon;
grant execute on function private.ranking() to anon,authenticated;
grant execute on function public.porikkhon_leaderboard() to anon,authenticated;
revoke all on function private.guard() from public,anon,authenticated;
revoke all on function private.plan(uuid) from public,anon,authenticated;
revoke all on function private.finish(text,uuid) from public,anon,authenticated;
revoke all on function private.report(text,uuid) from public,anon,authenticated;
revoke all on function private.public_questions(jsonb) from public,anon,authenticated;

insert into private.exam_catalog(id,meta,questions) values('admission-english','{"id":"admission-english","title":"English essentials","category":"Admission","subject":"English","minutes":12,"count":12,"penalty":0.25,"difficulty":"Foundation","color":"coral","kind":"Full model test","description":"Grammar, vocabulary, and the details that make a difference."}'::jsonb,'[{"id":"eng-1","stem":"Choose the correct sentence.","options":["She do not like tea.","She does not likes tea.","She does not like tea.","She not likes tea."],"answer":2,"explanation":"After does not, use the base form of the verb: like.","subject":"English","category":"Admission","difficulty":"Challenge"},{"id":"eng-2","stem":"Which word is closest in meaning to “concise”?","options":["Lengthy","Brief","Unclear","Repeated"],"answer":1,"explanation":"Concise means giving information clearly in few words; brief is the closest option.","subject":"English","category":"Admission","difficulty":"Foundation"},{"id":"eng-3","stem":"Choose the correct preposition: She is interested ___ science.","options":["on","at","in","with"],"answer":2,"explanation":"The standard expression is interested in something.","subject":"English","category":"Admission","difficulty":"Standard"},{"id":"eng-4","stem":"Choose the antonym of “scarce”.","options":["Rare","Limited","Abundant","Insufficient"],"answer":2,"explanation":"Scarce means not plentiful. Abundant means plentiful, so it is the opposite.","subject":"English","category":"Admission","difficulty":"Challenge"},{"id":"eng-5","stem":"Which sentence uses the present perfect tense?","options":["I visited Dhaka yesterday.","I have visited Dhaka.","I am visiting Dhaka.","I will visit Dhaka."],"answer":1,"explanation":"The present perfect uses have/has + past participle: have visited.","subject":"English","category":"Admission","difficulty":"Foundation"},{"id":"eng-6","stem":"Choose the correctly spelled word.","options":["Accomodation","Acommodation","Accommodation","Accommmodation"],"answer":2,"explanation":"Accommodation is spelled with two c letters and two m letters.","subject":"English","category":"Admission","difficulty":"Standard"},{"id":"eng-7","stem":"Fill in: Neither of the answers ___ correct.","options":["are","were","is","have"],"answer":2,"explanation":"In formal standard usage, neither is singular here and takes is.","subject":"English","category":"Admission","difficulty":"Challenge"},{"id":"eng-8","stem":"Identify the passive voice.","options":["They built the bridge.","The bridge was built by them.","They are building a bridge.","They will build it."],"answer":1,"explanation":"The subject receives the action in passive voice: was built.","subject":"English","category":"Admission","difficulty":"Foundation"},{"id":"eng-9","stem":"Choose the correct article: He is ___ honest person.","options":["a","an","the","no article"],"answer":1,"explanation":"Honest begins with a vowel sound because h is silent; use an.","subject":"English","category":"Admission","difficulty":"Standard"},{"id":"eng-10","stem":"“Although it was raining, we continued.” Although introduces:","options":["A reason","A contrast","A result","A place"],"answer":1,"explanation":"Although introduces a concession or contrast between the two clauses.","subject":"English","category":"Admission","difficulty":"Challenge"},{"id":"eng-11","stem":"Choose the correct form: If I ___ you, I would revise today.","options":["am","was","were","be"],"answer":2,"explanation":"The hypothetical expression uses the subjunctive: If I were you.","subject":"English","category":"Admission","difficulty":"Foundation"},{"id":"eng-12","stem":"Which word is a conjunction?","options":["Quickly","Under","Because","Beautiful"],"answer":2,"explanation":"Because connects clauses and introduces a reason; it is a conjunction.","subject":"English","category":"Admission","difficulty":"Standard"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;

insert into private.exam_catalog(id,meta,questions) values('admission-math','{"id":"admission-math","title":"Quantitative confidence","category":"Admission","subject":"Mathematics","minutes":15,"count":12,"penalty":0.25,"difficulty":"Standard","color":"teal","kind":"Subject test","description":"Build your problem-solving rhythm, one question at a time."}'::jsonb,'[{"id":"math-1","stem":"If 3x + 7 = 22, what is x?","options":["3","5","7","9"],"answer":1,"explanation":"Subtract 7 from both sides: 3x = 15. Divide by 3 to get x = 5.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"math-2","stem":"A number increases from 80 to 100. What is the percentage increase?","options":["20%","25%","30%","80%"],"answer":1,"explanation":"The increase is 20. Divide by the original 80 and multiply by 100: 25%.","subject":"Mathematics","category":"Admission","difficulty":"Foundation"},{"id":"math-3","stem":"What is the next number in 2, 6, 12, 20, 30, …?","options":["36","40","42","48"],"answer":2,"explanation":"The differences are 4, 6, 8, 10. The next difference is 12, so the answer is 42.","subject":"Mathematics","category":"Admission","difficulty":"Standard"},{"id":"math-4","stem":"The average of 8, 12, 16 and x is 14. Find x.","options":["16","18","20","22"],"answer":2,"explanation":"Four numbers with average 14 have total 56. The known numbers total 36, so x = 20.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"math-5","stem":"A fair die is rolled once. What is the probability of an even number?","options":["1/6","1/3","1/2","2/3"],"answer":2,"explanation":"There are three even outcomes (2, 4, 6) among six equally likely outcomes: 3/6 = 1/2.","subject":"Mathematics","category":"Admission","difficulty":"Foundation"},{"id":"math-6","stem":"If the radius of a circle doubles, its area becomes:","options":["Twice as large","Three times as large","Four times as large","Eight times as large"],"answer":2,"explanation":"Area is πr². Replacing r with 2r multiplies area by 4.","subject":"Mathematics","category":"Admission","difficulty":"Standard"},{"id":"math-7","stem":"Solve: 2² × 2³ = ?","options":["16","24","32","64"],"answer":2,"explanation":"When multiplying powers with the same base, add exponents: 2⁵ = 32.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"math-8","stem":"A train travels 150 km in 2.5 hours. Its average speed is:","options":["50 km/h","55 km/h","60 km/h","75 km/h"],"answer":2,"explanation":"Average speed = distance/time = 150/2.5 = 60 km/h.","subject":"Mathematics","category":"Admission","difficulty":"Foundation"},{"id":"math-9","stem":"If a:b = 2:3 and b:c = 4:5, then a:c is:","options":["2:5","8:15","3:5","4:15"],"answer":1,"explanation":"Use a common value b = 12. Then a = 8 and c = 15, giving 8:15.","subject":"Mathematics","category":"Admission","difficulty":"Standard"},{"id":"math-10","stem":"The sum of the interior angles of a hexagon is:","options":["540°","600°","720°","900°"],"answer":2,"explanation":"For n sides, the sum is (n−2) × 180°. For 6 sides, this is 720°.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"math-11","stem":"What is log₁₀(1000)?","options":["2","3","10","100"],"answer":1,"explanation":"10³ = 1000, so log₁₀(1000) = 3.","subject":"Mathematics","category":"Admission","difficulty":"Foundation"},{"id":"math-12","stem":"A shop gives a 10% discount on ৳500. What is the sale price?","options":["৳400","৳425","৳450","৳490"],"answer":2,"explanation":"10% of 500 is 50. Subtract the discount to get ৳450.","subject":"Mathematics","category":"Admission","difficulty":"Standard"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;

insert into private.exam_catalog(id,meta,questions) values('bcs-foundation','{"id":"bcs-foundation","title":"BCS knowledge builder","category":"BCS & Jobs","subject":"General knowledge","minutes":12,"count":12,"penalty":0.5,"difficulty":"Foundation","color":"lilac","kind":"Full model test","description":"Evergreen general knowledge with clear, useful explanations."}'::jsonb,'[{"id":"gk-1","stem":"বাংলাদেশের স্বাধীনতা দিবস কবে?","options":["২১ ফেব্রুয়ারি","২৬ মার্চ","১৬ ডিসেম্বর","১৪ এপ্রিল"],"answer":1,"explanation":"বাংলাদেশের স্বাধীনতা দিবস ২৬ মার্চ। বিজয় দিবস ১৬ ডিসেম্বর।","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Challenge"},{"id":"gk-2","stem":"The United Nations was established in which year?","options":["1919","1945","1948","1952"],"answer":1,"explanation":"The United Nations officially came into existence on 24 October 1945.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Foundation"},{"id":"gk-3","stem":"Which organ pumps blood through the human body?","options":["Liver","Kidney","Heart","Lung"],"answer":2,"explanation":"The heart generates the pressure that circulates blood through the body.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Standard"},{"id":"gk-4","stem":"বাংলা বর্ণমালায় প্রচলিত স্বরবর্ণের সংখ্যা কত?","options":["৯","১০","১১","১২"],"answer":2,"explanation":"বাংলা বর্ণমালায় প্রচলিত স্বরবর্ণ ১১টি।","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Challenge"},{"id":"gk-5","stem":"Which is the largest ocean on Earth?","options":["Atlantic","Indian","Arctic","Pacific"],"answer":3,"explanation":"The Pacific Ocean has the largest surface area of all oceans.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Foundation"},{"id":"gk-6","stem":"The chemical symbol for gold is:","options":["Ag","Au","Fe","Gd"],"answer":1,"explanation":"Au comes from the Latin word aurum and is the chemical symbol for gold.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Standard"},{"id":"gk-7","stem":"বাংলাদেশের জাতীয় ফুল কোনটি?","options":["গোলাপ","শাপলা","জবা","বেলি"],"answer":1,"explanation":"শাপলা বাংলাদেশের জাতীয় ফুল।","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Challenge"},{"id":"gk-8","stem":"Which gas do plants primarily absorb during photosynthesis?","options":["Oxygen","Nitrogen","Carbon dioxide","Hydrogen"],"answer":2,"explanation":"Plants use carbon dioxide and water to produce sugars during photosynthesis.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Foundation"},{"id":"gk-9","stem":"Who wrote “Hamlet”?","options":["William Shakespeare","Charles Dickens","Jane Austen","John Milton"],"answer":0,"explanation":"Hamlet is a tragedy written by William Shakespeare.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Standard"},{"id":"gk-10","stem":"The SI unit of electric current is:","options":["Volt","Ohm","Watt","Ampere"],"answer":3,"explanation":"The ampere is the SI base unit of electric current.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Challenge"},{"id":"gk-11","stem":"The Earth takes approximately how long to orbit the Sun?","options":["24 hours","30 days","365.25 days","10 years"],"answer":2,"explanation":"One orbit takes about 365.25 days, which is the basis for a year.","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Foundation"},{"id":"gk-12","stem":"রবীন্দ্রনাথ ঠাকুর কোন কাব্যগ্রন্থের জন্য নোবেল পুরস্কার পান?","options":["সোনার তরী","গীতাঞ্জলি","বলাকা","সঞ্চয়িতা"],"answer":1,"explanation":"রবীন্দ্রনাথ ঠাকুর ১৯১৩ সালে গীতাঞ্জলির ইংরেজি অনুবাদের জন্য সাহিত্যে নোবেল পুরস্কার পান।","subject":"General knowledge","category":"BCS & Jobs","difficulty":"Standard"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;

insert into private.exam_catalog(id,meta,questions) values('hsc-science','{"id":"hsc-science","title":"Science, made clearer","category":"SSC & HSC","subject":"Science","minutes":15,"count":12,"penalty":0,"difficulty":"Standard","color":"lime","kind":"Subject test","description":"Reconnect the ideas behind physics, chemistry, and biology."}'::jsonb,'[{"id":"sci-1","stem":"Which SI unit measures force?","options":["Joule","Newton","Watt","Pascal"],"answer":1,"explanation":"The newton is the SI unit of force. One newton equals one kilogram metre per second squared.","subject":"Science","category":"SSC & HSC","difficulty":"Challenge"},{"id":"sci-2","stem":"A body of mass 2 kg accelerates at 3 m/s². The net force is:","options":["1.5 N","5 N","6 N","9 N"],"answer":2,"explanation":"Newton’s second law gives F = ma = 2 × 3 = 6 N.","subject":"Science","category":"SSC & HSC","difficulty":"Foundation"},{"id":"sci-3","stem":"A solution with pH 3 is:","options":["Acidic","Neutral","Basic","Always pure water"],"answer":0,"explanation":"A pH below 7 is acidic under ordinary aqueous conditions.","subject":"Science","category":"SSC & HSC","difficulty":"Standard"},{"id":"sci-4","stem":"Which structure is commonly called the powerhouse of the cell?","options":["Nucleus","Ribosome","Mitochondrion","Cell wall"],"answer":2,"explanation":"Mitochondria produce much of the ATP used by eukaryotic cells.","subject":"Science","category":"SSC & HSC","difficulty":"Challenge"},{"id":"sci-5","stem":"At constant temperature, pressure and volume of a fixed gas sample are:","options":["Directly proportional","Inversely proportional","Always equal","Unrelated"],"answer":1,"explanation":"Boyle’s law states PV is constant for a fixed amount of gas at constant temperature.","subject":"Science","category":"SSC & HSC","difficulty":"Foundation"},{"id":"sci-6","stem":"Which cell structure controls the movement of substances into and out of a cell?","options":["Ribosome","Chromosome","Cell membrane","Nucleolus"],"answer":2,"explanation":"The selectively permeable cell membrane regulates movement between the cell and its surroundings.","subject":"Science","category":"SSC & HSC","difficulty":"Standard"},{"id":"sci-7","stem":"Which quantity is a vector?","options":["Mass","Temperature","Speed","Velocity"],"answer":3,"explanation":"Velocity has both magnitude and direction; speed is a scalar.","subject":"Science","category":"SSC & HSC","difficulty":"Challenge"},{"id":"sci-8","stem":"The atomic number of an element equals its number of:","options":["Neutrons","Protons","Protons plus neutrons","Electron shells"],"answer":1,"explanation":"Atomic number is defined as the number of protons in the nucleus.","subject":"Science","category":"SSC & HSC","difficulty":"Foundation"},{"id":"sci-9","stem":"Which blood cells mainly transport oxygen?","options":["Red blood cells","White blood cells","Platelets","All equally"],"answer":0,"explanation":"Hemoglobin in red blood cells binds and transports oxygen.","subject":"Science","category":"SSC & HSC","difficulty":"Standard"},{"id":"sci-10","stem":"A 10 Ω resistor carries 2 A. The voltage across it is:","options":["5 V","12 V","20 V","40 V"],"answer":2,"explanation":"Ohm’s law gives V = IR = 2 × 10 = 20 V.","subject":"Science","category":"SSC & HSC","difficulty":"Challenge"},{"id":"sci-11","stem":"Which process changes a liquid directly into a gas at its surface?","options":["Freezing","Evaporation","Condensation","Melting"],"answer":1,"explanation":"Evaporation is vaporization that occurs at the surface of a liquid.","subject":"Science","category":"SSC & HSC","difficulty":"Foundation"},{"id":"sci-12","stem":"In a controlled experiment, which variable does the investigator deliberately change?","options":["Independent variable","Dependent variable","Every variable","Measured outcome only"],"answer":0,"explanation":"The independent variable is deliberately changed. Its effect on the dependent variable is measured while other relevant conditions are controlled.","subject":"Science","category":"SSC & HSC","difficulty":"Standard"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;

insert into private.exam_catalog(id,meta,questions) values('skill-aptitude','{"id":"skill-aptitude","title":"Think a little sharper","category":"Skills","subject":"Aptitude & computing","minutes":12,"count":12,"penalty":0.25,"difficulty":"Challenge","color":"peach","kind":"Skills assessment","description":"Logic, computing fundamentals, and practical reasoning."}'::jsonb,'[{"id":"skill-1","stem":"Which data structure follows FIFO order?","options":["Stack","Queue","Tree","Set"],"answer":1,"explanation":"A queue removes items in first-in, first-out order.","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-2","stem":"The binary number 1010 equals which decimal number?","options":["8","9","10","12"],"answer":2,"explanation":"1010₂ = 8 + 0 + 2 + 0 = 10.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"},{"id":"skill-3","stem":"Which SQL clause filters groups after aggregation?","options":["WHERE","ORDER BY","HAVING","JOIN"],"answer":2,"explanation":"HAVING filters grouped results; WHERE filters rows before grouping.","subject":"Aptitude & computing","category":"Skills","difficulty":"Standard"},{"id":"skill-4","stem":"In a sorted array, binary search has worst-case time complexity:","options":["O(1)","O(log n)","O(n)","O(n²)"],"answer":1,"explanation":"Binary search halves the remaining search interval at each step, giving O(log n).","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-5","stem":"Which is the strongest general password practice?","options":["Reuse a short password","Use a unique long password with a password manager","Share it with a trusted classmate","Use your birth date"],"answer":1,"explanation":"Unique, long passwords stored in a password manager reduce reuse and guessing risks.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"},{"id":"skill-6","stem":"What does HTTP status 404 commonly indicate?","options":["Success","Unauthorized request","Resource not found","Server maintenance only"],"answer":2,"explanation":"HTTP 404 means the server did not find the requested resource.","subject":"Aptitude & computing","category":"Skills","difficulty":"Standard"},{"id":"skill-7","stem":"Which is a valid IPv4 address?","options":["192.168.1.1","300.168.1.1","192.168.1","192.168.one.1"],"answer":0,"explanation":"IPv4 uses four decimal octets, each between 0 and 255.","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-8","stem":"If all roses are flowers and some flowers fade quickly, which must be true?","options":["All roses fade quickly","No roses fade quickly","All roses are flowers","Some roses are not flowers"],"answer":2,"explanation":"Only the first premise about all roses necessarily follows. The fading statement does not identify roses.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"},{"id":"skill-9","stem":"A task takes 6 people 10 days. At the same per-person rate, 3 people take:","options":["5 days","10 days","15 days","20 days"],"answer":3,"explanation":"The work is 60 person-days. With 3 people it takes 60/3 = 20 days.","subject":"Aptitude & computing","category":"Skills","difficulty":"Standard"},{"id":"skill-10","stem":"Which technique helps prevent SQL injection?","options":["String concatenation","Parameterized queries","Hiding the login button","Using shorter table names"],"answer":1,"explanation":"Parameterized queries separate SQL instructions from data supplied by users.","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-11","stem":"What is 15% of 240?","options":["24","30","36","48"],"answer":2,"explanation":"0.15 × 240 = 36.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"},{"id":"skill-12","stem":"A logical AND expression is true when:","options":["At least one input is true","Both inputs are true","Both inputs are false","The first input is false"],"answer":1,"explanation":"AND returns true only when both operands are true.","subject":"Aptitude & computing","category":"Skills","difficulty":"Standard"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;

insert into private.exam_catalog(id,meta,questions) values('mixed-foundation','{"id":"mixed-foundation","title":"Your foundation check","category":"All tracks","subject":"Mixed","minutes":20,"count":20,"penalty":0.25,"difficulty":"Standard","color":"sky","kind":"Mixed practice","description":"A balanced check-in across English, mathematics, and science."}'::jsonb,'[{"id":"math-1","stem":"If 3x + 7 = 22, what is x?","options":["3","5","7","9"],"answer":1,"explanation":"Subtract 7 from both sides: 3x = 15. Divide by 3 to get x = 5.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"eng-1","stem":"Choose the correct sentence.","options":["She do not like tea.","She does not likes tea.","She does not like tea.","She not likes tea."],"answer":2,"explanation":"After does not, use the base form of the verb: like.","subject":"English","category":"Admission","difficulty":"Challenge"},{"id":"sci-1","stem":"Which SI unit measures force?","options":["Joule","Newton","Watt","Pascal"],"answer":1,"explanation":"The newton is the SI unit of force. One newton equals one kilogram metre per second squared.","subject":"Science","category":"SSC & HSC","difficulty":"Challenge"},{"id":"math-2","stem":"A number increases from 80 to 100. What is the percentage increase?","options":["20%","25%","30%","80%"],"answer":1,"explanation":"The increase is 20. Divide by the original 80 and multiply by 100: 25%.","subject":"Mathematics","category":"Admission","difficulty":"Foundation"},{"id":"eng-2","stem":"Which word is closest in meaning to “concise”?","options":["Lengthy","Brief","Unclear","Repeated"],"answer":1,"explanation":"Concise means giving information clearly in few words; brief is the closest option.","subject":"English","category":"Admission","difficulty":"Foundation"},{"id":"sci-2","stem":"A body of mass 2 kg accelerates at 3 m/s². The net force is:","options":["1.5 N","5 N","6 N","9 N"],"answer":2,"explanation":"Newton’s second law gives F = ma = 2 × 3 = 6 N.","subject":"Science","category":"SSC & HSC","difficulty":"Foundation"},{"id":"math-3","stem":"What is the next number in 2, 6, 12, 20, 30, …?","options":["36","40","42","48"],"answer":2,"explanation":"The differences are 4, 6, 8, 10. The next difference is 12, so the answer is 42.","subject":"Mathematics","category":"Admission","difficulty":"Standard"},{"id":"eng-3","stem":"Choose the correct preposition: She is interested ___ science.","options":["on","at","in","with"],"answer":2,"explanation":"The standard expression is interested in something.","subject":"English","category":"Admission","difficulty":"Standard"},{"id":"sci-3","stem":"A solution with pH 3 is:","options":["Acidic","Neutral","Basic","Always pure water"],"answer":0,"explanation":"A pH below 7 is acidic under ordinary aqueous conditions.","subject":"Science","category":"SSC & HSC","difficulty":"Standard"},{"id":"math-4","stem":"The average of 8, 12, 16 and x is 14. Find x.","options":["16","18","20","22"],"answer":2,"explanation":"Four numbers with average 14 have total 56. The known numbers total 36, so x = 20.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"eng-4","stem":"Choose the antonym of “scarce”.","options":["Rare","Limited","Abundant","Insufficient"],"answer":2,"explanation":"Scarce means not plentiful. Abundant means plentiful, so it is the opposite.","subject":"English","category":"Admission","difficulty":"Challenge"},{"id":"sci-4","stem":"Which structure is commonly called the powerhouse of the cell?","options":["Nucleus","Ribosome","Mitochondrion","Cell wall"],"answer":2,"explanation":"Mitochondria produce much of the ATP used by eukaryotic cells.","subject":"Science","category":"SSC & HSC","difficulty":"Challenge"},{"id":"math-5","stem":"A fair die is rolled once. What is the probability of an even number?","options":["1/6","1/3","1/2","2/3"],"answer":2,"explanation":"There are three even outcomes (2, 4, 6) among six equally likely outcomes: 3/6 = 1/2.","subject":"Mathematics","category":"Admission","difficulty":"Foundation"},{"id":"eng-5","stem":"Which sentence uses the present perfect tense?","options":["I visited Dhaka yesterday.","I have visited Dhaka.","I am visiting Dhaka.","I will visit Dhaka."],"answer":1,"explanation":"The present perfect uses have/has + past participle: have visited.","subject":"English","category":"Admission","difficulty":"Foundation"},{"id":"sci-5","stem":"At constant temperature, pressure and volume of a fixed gas sample are:","options":["Directly proportional","Inversely proportional","Always equal","Unrelated"],"answer":1,"explanation":"Boyle’s law states PV is constant for a fixed amount of gas at constant temperature.","subject":"Science","category":"SSC & HSC","difficulty":"Foundation"},{"id":"math-6","stem":"If the radius of a circle doubles, its area becomes:","options":["Twice as large","Three times as large","Four times as large","Eight times as large"],"answer":2,"explanation":"Area is πr². Replacing r with 2r multiplies area by 4.","subject":"Mathematics","category":"Admission","difficulty":"Standard"},{"id":"eng-6","stem":"Choose the correctly spelled word.","options":["Accomodation","Acommodation","Accommodation","Accommmodation"],"answer":2,"explanation":"Accommodation is spelled with two c letters and two m letters.","subject":"English","category":"Admission","difficulty":"Standard"},{"id":"sci-6","stem":"Which cell structure controls the movement of substances into and out of a cell?","options":["Ribosome","Chromosome","Cell membrane","Nucleolus"],"answer":2,"explanation":"The selectively permeable cell membrane regulates movement between the cell and its surroundings.","subject":"Science","category":"SSC & HSC","difficulty":"Standard"},{"id":"math-7","stem":"Solve: 2² × 2³ = ?","options":["16","24","32","64"],"answer":2,"explanation":"When multiplying powers with the same base, add exponents: 2⁵ = 32.","subject":"Mathematics","category":"Admission","difficulty":"Challenge"},{"id":"eng-7","stem":"Fill in: Neither of the answers ___ correct.","options":["are","were","is","have"],"answer":2,"explanation":"In formal standard usage, neither is singular here and takes is.","subject":"English","category":"Admission","difficulty":"Challenge"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;

insert into private.exam_catalog(id,meta,questions) values('daily-challenge','{"id":"daily-challenge","title":"The daily reasoning sprint","category":"Skills","subject":"Aptitude & computing","minutes":8,"count":8,"penalty":0.25,"difficulty":"Challenge","color":"teal","kind":"Live challenge","description":"Join the daily 8 PM Bangladesh-time challenge. Practice with purpose."}'::jsonb,'[{"id":"skill-1","stem":"Which data structure follows FIFO order?","options":["Stack","Queue","Tree","Set"],"answer":1,"explanation":"A queue removes items in first-in, first-out order.","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-2","stem":"The binary number 1010 equals which decimal number?","options":["8","9","10","12"],"answer":2,"explanation":"1010₂ = 8 + 0 + 2 + 0 = 10.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"},{"id":"skill-3","stem":"Which SQL clause filters groups after aggregation?","options":["WHERE","ORDER BY","HAVING","JOIN"],"answer":2,"explanation":"HAVING filters grouped results; WHERE filters rows before grouping.","subject":"Aptitude & computing","category":"Skills","difficulty":"Standard"},{"id":"skill-4","stem":"In a sorted array, binary search has worst-case time complexity:","options":["O(1)","O(log n)","O(n)","O(n²)"],"answer":1,"explanation":"Binary search halves the remaining search interval at each step, giving O(log n).","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-5","stem":"Which is the strongest general password practice?","options":["Reuse a short password","Use a unique long password with a password manager","Share it with a trusted classmate","Use your birth date"],"answer":1,"explanation":"Unique, long passwords stored in a password manager reduce reuse and guessing risks.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"},{"id":"skill-6","stem":"What does HTTP status 404 commonly indicate?","options":["Success","Unauthorized request","Resource not found","Server maintenance only"],"answer":2,"explanation":"HTTP 404 means the server did not find the requested resource.","subject":"Aptitude & computing","category":"Skills","difficulty":"Standard"},{"id":"skill-7","stem":"Which is a valid IPv4 address?","options":["192.168.1.1","300.168.1.1","192.168.1","192.168.one.1"],"answer":0,"explanation":"IPv4 uses four decimal octets, each between 0 and 255.","subject":"Aptitude & computing","category":"Skills","difficulty":"Challenge"},{"id":"skill-8","stem":"If all roses are flowers and some flowers fade quickly, which must be true?","options":["All roses fade quickly","No roses fade quickly","All roses are flowers","Some roses are not flowers"],"answer":2,"explanation":"Only the first premise about all roses necessarily follows. The fading statement does not identify roses.","subject":"Aptitude & computing","category":"Skills","difficulty":"Foundation"}]'::jsonb) on conflict(id) do update set meta=excluded.meta,questions=excluded.questions;
create or replace function private.payment_order(order_id text) returns jsonb language sql security definer set search_path='' as $$select to_jsonb(p) from private.payments p where id=order_id$$;
create or replace function private.payment_confirm(order_id text,validation_id text) returns boolean language plpgsql security definer set search_path='' as $$begin update private.payments p set status='paid',confirmed_at=floor(extract(epoch from now())*1000),validation_id=payment_confirm.validation_id where p.id=order_id and status in ('pending','review');return exists(select 1 from private.payments where id=order_id and status='paid');end$$;
create or replace function public.porikkhon_payment_order(order_id text) returns jsonb language sql security invoker set search_path='' as $$select private.payment_order(order_id)$$;
create or replace function public.porikkhon_payment_confirm(order_id text,validation_id text) returns boolean language sql security invoker set search_path='' as $$select private.payment_confirm(order_id,validation_id)$$;
revoke all on function public.porikkhon_payment_order(text),public.porikkhon_payment_confirm(text,text),private.payment_order(text),private.payment_confirm(text,text) from public,anon,authenticated;
grant usage on schema private to service_role;
grant execute on function public.porikkhon_payment_order(text),public.porikkhon_payment_confirm(text,text),private.payment_order(text),private.payment_confirm(text,text) to service_role;
